	include "Debug.rsrc" not 'ckid';	#endif	include "Dialog.rsrc" not 'ckid';	include "MacApp.rsrc" not 'ckid';	// Includes for Building Blocks	include "Printing.rsrc" not 'ckid';	// Include Code Resources	#if !qNoCode		include $$Shell("ObjApp")$$Shell("XAppName") 'CODE';		#if qModelCFM			include $$Shell("ObjApp")$$Shell("XAppName") 'cfrg';			include $$Shell("ObjApp")$$Shell("XAppName") 'rseg';		#endif	#endif	#define kApplicationName	TARGET_APPLICATION_NAME#else	include kDefaultRsrcName  'CMNU' (mApple);			// Grab the default Apple menus	include kDefaultRsrcName  'CMNU' (mFile);			// Grab the default File menus	include kDefaultRsrcName  'CMNU' (mEdit);			// Grab the default Edit menu	include kDefaultRsrcName  'ALRT' (phAboutApp);		// Grab the default about box	include kDefaultRsrcName  'aete' (0);				// Grab the default AppleEvent terminology	include kDefaultRsrcName  'STR#' (kDefaultCredits);	// Grab the default credits	include kDefaultRsrcName  'vers' (2);				// Overall package	include kDefaultRsrcName  'ICN#' (kApplicationID);	// MacApp Family large black & white		include kDefaultRsrcName  'ICN#' (kDocumentID);		// MacApp Document large black & white	include kDefaultRsrcName  'ICN#' (kStationeryID);	// MacApp Stationery large black & white		include kDefaultRsrcName  'ics#' (kApplicationID);	// MacApp Family small black & white		include kDefaultRsrcName  'ics#' (kDocumentID);		// MacApp Document small black & white	include kDefaultRsrcName  'ics#' (kStationeryID);	// MacApp Stationery small black & white	include kDefaultRsrcName  'ics4' (kApplicationID);	// MacApp Family small 4 bit	include kDefaultRsrcName  'ics4' (kDocumentID);		// MacApp Document small 4 bit	include kDefaultRsrcName  'ics4' (kStationeryID);	// MacApp Stationery small 4 bit	include kDefaultRsrcName  'ics8' (kApplicationID);	// MacApp Family small 4 bit	include kDefaultRsrcName  'ics8' (kDocumentID);		// MacApp Document small 4 bit	include kDefaultRsrcName  'ics8' (kStationeryID);	// MacApp Stationery small 4 bit	include kDefaultRsrcName  'icl4' (kApplicationID);	// MacApp Family large 4 bit	include kDefaultRsrcName  'icl4' (kDocumentID);		// MacApp Document large 4 bit	include kDefaultRsrcName  'icl4' (kStationeryID);	// MacApp Stationery large 4 bit	include kDefaultRsrcName  'icl8' (kApplicationID);	// MacApp Family large 8 bit	include kDefaultRsrcName  'icl8' (kDocumentID);		// MacApp Document large 8 bit	include kDefaultRsrcName  'icl8' (kStationeryID);	// MacApp Stationery large 8 bit	#if !qCarbon		include kDefaultRsrcName  'hmnu' (mFile);			include kDefaultRsrcName  'hmnu' (mEdit);		#endif	#define kApplicationName	$$Shell("XAppName")#endif //!THINK_Rez//--------------------------------------------------------------------------------------------------// RESOURCES FOR MENUS //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// Menu Bars //--------------------------------------------------------------------------------------------------resource 'MBAR' (kMBarDisplayed,#if qNames"DemoNet MBAR",#endif	purgeable) {	{ mApple; mFile; mEdit; mDemoNetMenu }};//--------------------------------------------------------------------------------------------------// Menus //--------------------------------------------------------------------------------------------------resource 'CMNU' (mDemoNetMenu,#if qNames"DemoNet Menu",#endifnonpurgeable) {	mDemoNetMenu,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"DemoNetMenu",	{	/* array: 4 elements */		/* [1] */	"Ping...", noIcon, "1", noMark, plain, cPing;		/* [2] */	"Terminal...", noIcon, "2", noMark, plain, cTerminal;		/* [3] */	"-", noIcon, noKey, noMark, plain, noCommand;//		/* [4] */	"Message", noIcon, "M", noMark, plain, cMessage;	}};resource 'CMNU' (mBuzzwords,#if qNames"Buzzwords",#endifpurgeable) {	mBuzzwords,	textMenuProc,	EnablingManagedByMacApp,	enabled,	"Buzzwords",	 {	/* array: 13 elements */		"Page Setup Change",	noIcon,	noKey,	noMark, plain, cChangePrinterStyle;		"Typing",				noIcon,	noKey,	noMark,	plain, cTyping;		"Connect",				noIcon,	noKey,	noMark,	plain, cConnected;		"Send",					noIcon,	noKey,	noMark,	plain, cSent;		"Receive",				noIcon,	noKey,	noMark,	plain, cReceived;	}};//--------------------------------------------------------------------------------------------------// Balloon Help Resources for Menus //--------------------------------------------------------------------------------------------------// Includes resource 'STR#' (kStandardHelpStrings, "Balloon Help String 1")// with our application name substituted in strings#include "HelpStrings.r"resource 'STR#' (kDemoNetMenuHelp, purgeable) { 	{		"No help yet for this  item",		"Help For Menu Title",		"Help For First Menu Item",		"Help For Second Menu Item",		"Help For Third Menu Item",	}};#if !qCarbonresource 'hmnu' (mDemoNetMenu) {	HelpMgrVersion,	hmDefaultOptions,	0, // balloon definition function 	0, // variation code 		// Missing items 	HMStringResItem 	{		kDemoNetMenuHelp,1,		kDemoNetMenuHelp,1,		kDemoNetMenuHelp,1,		kDemoNetMenuHelp,1,	},		// Title and items 	{			// Title 		HMStringResItem 		{			kDemoNetMenuHelp,2,			kDemoNetMenuHelp,2,			kDemoNetMenuHelp,2,			kDemoNetMenuHelp,2,		},		// First Item 		HMStringResItem 		{			kDemoNetMenuHelp,3,			kDemoNetMenuHelp,3,			kDemoNetMenuHelp,3,			kDemoNetMenuHelp,3,		},		// Second Item		HMStringResItem 		{			kDemoNetMenuHelp,4,			kDemoNetMenuHelp,4,			kDemoNetMenuHelp,4,			kDemoNetMenuHelp,4,		},		// Third Item		HMStringResItem 		{			kDemoNetMenuHelp,5,			kDemoNetMenuHelp,5,			kDemoNetMenuHelp,5,			kDemoNetMenuHelp,5,		},	}};#endif//--------------------------------------------------------------------------------------------------// RESOURCES FOR VIEWS, DIALOGS, ALERTS etc. //--------------------------------------------------------------------------------------------------//--------------------------------------------------------------------------------------------------// About Box//--------------------------------------------------------------------------------------------------resource 'DITL' (phAboutApp,#if qNames"phAboutApp",#endif	purgeable) {	 {	/* array DITLarray: 3 elements */		/* [1] */		{167, 288, 187, 348},		Button {			enabled,			"OK"		};		/* [2] */		{10, 75, 154, 348},		StaticText {			disabled,			"This sample program demonstrates large views and mouse tracking."			"\n"			WRITTEN_WITH_MACAPP		};		/* [3] */		{10, 20, 42, 52},		Icon {			disabled,			noteIcon		}	}};//--------------------------------------------------------------------------------------------------// MultiFinder™ information//--------------------------------------------------------------------------------------------------/* Additional size deltas to be added to partition size */#if qNames#define kNamesSizeDelta 75#else#define kNamesSizeDelta 0#endif#if qDebug#define kDebugSizeDelta 0#else#define kDebugSizeDelta 0#endif#define kModelFarSizeDelta 0#ifndef MW_Rez					// MW projects supply size resource for usresource 'SIZE' (-1) {	saveScreen,	acceptSuspendResumeEvents,	enableOptionSwitch,	canBackground,	doesActivateOnFGSwitch,	backgroundAndForeground,	dontGetFrontClicks,	ignoreAppDiedEvents,	is32BitCompatible,	isHighLevelEventAware,	localAndRemoteHLEvents,	notStationeryAware,					reserved,	reserved,	reserved,	reserved,		/* Suggested partition size */	(1000 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024,		/* Minimum partition size */	(800 + kNamesSizeDelta + kDebugSizeDelta + kModelFarSizeDelta) * 1024};#endif // !MW_Rez//--------------------------------------------------------------------------------------------------// Memory usage information for DemoNet//--------------------------------------------------------------------------------------------------// See UMemory.h// -------------// Code fragment resource for PowerPC native apps// ----------------------------------------------#ifndef MW_Rez 	// Metrowerks will supply it's own cfrg#if qPowerPC#include "CodeFragmentTypes.r"resource 'cfrg' (0, "Configuration Info") {	{		kPowerPC,		kFullLib,		kNoVersionNum,		kNoVersionNum,		0,		0,		kIsApp,		kOnDiskFlat,		kZeroOffset,		kWholeFork,		"DemoNet"	}};#endif#endif // MW_Rez//--------------------------------------------------------------------------------------------------// Icons, Bundles and FRefs… Oh my! (don't forget the Signature)//--------------------------------------------------------------------------------------------------type kSignature as 'STR ';resource kSignature (0,#if qNames"Signature",#endif	purgeable) {	"DemoNet ©Apple Computer, Inc. 1988-2000"};resource 'FREF' (kApplicationID,#if qNames"DemoNet Application",#endif	purgeable) {	'APPL',	0,	""};resource 'FREF' (kDocumentID,#if qNames"DemoNet Document",#endif	purgeable) {	kFileType,	1,	""};resource 'FREF' (kStationeryID,#if qNames"DemoNet Stationery",#endif	purgeable) {	kStationery,	2,	""};resource 'BNDL' (kBundleID,#if qNames"DemoNet",#endif	purgeable) {	kSignature,	0,	{ /* array TypeArray: 2 elements */		/* [1] */		'ICN#',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		},		/* [2] */		'FREF',		{ /* array IDArray: 3 elements */			0, kApplicationID,			1, kDocumentID,			2, kStationeryID		}	}};//--------------------------------------------------------------------------------------------------//  Version resources//--------------------------------------------------------------------------------------------------// The revision of this particular fileRESOURCE 'vers' (1,#if qNames"File Version",#endif	purgeable) {	0x01,	0x01,	development,	0x01,	verUs,	"1.1d1",	"DemoNet 1.1d1, ©Apple Computer, Inc. 1988-2000"};//--------------------------------------------------------------------------------------------------// End of DemoNet.r